/**
 * Get the list of secret keys a service references
 *
 * Reads from .tsdevstack/secret-map.json (committed to git, generated by generate-secrets).
 * Falls back to generating on-the-fly if the file doesn't exist.
 */

import path from 'node:path';
import { getContext } from '../../context';
import type { FrameworkConfig } from 'tsdevstack/plugin';

/**
 * Get the secret keys a specific service needs
 *
 * @param serviceName - Name of the service
 * @param config - Framework configuration
 * @returns Array of secret key names this service references
 */
export function getServiceSecretKeys(
  serviceName: string,
  config: FrameworkConfig,
): string[] {
  const {
    readJsonFile,
    findProjectRoot,
    TSDEVSTACK_DIR,
    SECRET_MAP_FILENAME,
    generateFrameworkSecretsFile,
    loadUserSecrets,
  } = getContext();

  // Try reading from committed secret-map.json
  const secretMapPath = path.join(
    findProjectRoot(),
    TSDEVSTACK_DIR,
    SECRET_MAP_FILENAME,
  );
  const secretMap = readJsonFile(secretMapPath) as Record<
    string,
    string[]
  > | null;

  if (secretMap) {
    return secretMap[serviceName] ?? [];
  }

  // Fallback: generate on-the-fly from framework + user secrets
  const frameworkSecrets = generateFrameworkSecretsFile(config, null);
  const userSecrets = loadUserSecrets();

  // Extract secrets arrays from both sources
  const fwEntry = frameworkSecrets[serviceName];
  const fwKeys = getSecretsArrayFromEntry(fwEntry);

  const userKeys = userSecrets
    ? getSecretsArrayFromEntry(userSecrets[serviceName])
    : [];

  // Deduplicated union
  return Array.from(new Set([...fwKeys, ...userKeys]));
}

/**
 * Extract secrets array from a service entry
 */
function getSecretsArrayFromEntry(entry: unknown): string[] {
  if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
    return [];
  }
  const secrets = (entry as Record<string, unknown>).secrets;
  return Array.isArray(secrets) ? (secrets as string[]) : [];
}
